fn sweep_task_factory(sweeper: Sweeper) -> SweepTaskFactory {
    Rc::new(move |scope, parent_node_seed| {
        let run = sweeper(scope, parent_node_seed, SWEEP_MAX_PASSES);
        Box::pin(async move {
            let _ = run.await;
        })
    })
}

